Lemma ro_cells_rheap_pres' : forall LB SP m m' A cs,
  rheap_pres LB SP m m' -> ro_cells rsegs m A cs -> rclient_range LB SP A (Z.of_nat (cells_size cs)) -> ro_cells rsegs m' A cs.
Proof.
  intros LB SP m m' A cs HP [Hwf HB] HR. split; [exact Hwf|].
  eapply rheap_pres_bytes_at; eauto. rewrite cells_bytes_length by assumption. exact HR.
Qed.

