  (* [comment removed for export] *)
  Definition pb_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (V A x lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch [(lo, bv_unsigned sp); (V, V + 24); (A, A + 8)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' V [C8 (Z_to_bv 64 A); C8 (Z_to_bv 64 (A + 8)); C8 (Z_to_bv 64 (A + 8))]
      /\ rw_cells rsegs m' A [C8 (Z_to_bv 64 x)].

  Lemma pb_seg2 : forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (V X A x lo : Z) (junkF junkA : list byte),
    rw_cells rsegs m (bv_unsigned sp + -80) [CB 32 junkF; C8 (Z_to_bv 64 V); C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
    rw_cells rsegs m (bv_unsigned sp + -96) [C8 (Z_to_bv 64 V); C8 (Z_to_bv 64 0x35bfc)] ->
    rw_cells rsegs m V [C8 (wz 0); C8 (wz 0); C8 (wz 0)] ->
    ro_cells rsegs m X [C8 (wz x)] ->
    rw_cells rsegs m A [CB 8 junkA] ->
    stk rsegs m lo (bv_unsigned sp + -96) -> lo + 96 <= bv_unsigned sp ->
    (V + 24 <= lo \/ bv_unsigned sp <= V) -> (X + 8 <= lo \/ bv_unsigned sp <= X) ->
    (X + 8 <= A \/ A + 8 <= X) -> (V + 24 <= A \/ A + 8 <= V) -> (X + 8 <= V \/ V + 24 <= X) ->
    0 < A -> A + 8 <= lo -> 0 <= x < 2^64 ->
    mem_inv rsegs m ->
    evt rsegs (pb_seg2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc V A x lo m)
      (MS (mkR (Z_to_bv 64 P_PUSHBACK_RET1) (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2
               (Z_to_bv 64 1) (Z_to_bv 64 X) (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7
               (Z_to_bv 64 0) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_PUSHBACK_RET1) fc None m (seg_rom rsegs)).
